import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Limbs and Trauma","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat/limbs-and-trauma.md","filePath":"guide/combat/limbs-and-trauma.md"}'),o={name:"guide/combat/limbs-and-trauma.md"};function r(s,e,l,d,m,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="limbs-and-trauma" tabindex="-1">Limbs and Trauma <a class="header-anchor" href="#limbs-and-trauma" aria-label="Permalink to &quot;Limbs and Trauma&quot;">​</a></h1><ul><li><strong>Design status:</strong> Accepted separation and Experimental local integrity; Proposed expanded injuries.</li><li><strong>Implementation:</strong> Stage 2A natural melee/local state; functional shield consequence deferred.</li><li><strong>Availability:</strong> no new live behavior established here; current configuration not inspected.</li><li><strong>Verification:</strong> documentation reviewed 2026-10-08; no new playtest. Existing evidence is scoped in <a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">combat status</a>.</li></ul><h2 id="health-is-not-the-whole-story" tabindex="-1">Health is not the whole story <a class="header-anchor" href="#health-is-not-the-whole-story" aria-label="Permalink to &quot;Health is not the whole story&quot;">​</a></h2><p>Global health still determines survival. Local integrity describes the condition of Head, Neck, Torso, Left Arm, Right Arm, Left Leg and Right Leg. A successful hit can damage health and the region it actually strikes. Armor condition is a third, separate concern; future bleeding is a condition proposal, not another name for local trauma.</p><p>A region progresses from Healthy through Wounded, Injured and Severe to Disabled. Disabled means loss of function in the design, not automatic severing. The current experiment records these states; it does not yet make an injured leg slow movement or a disabled head cause instant death. Shield loss to the backpack is approved intent but remains deferred.</p><h2 id="recovery-is-still-an-experiment" tabindex="-1">Recovery is still an experiment <a class="header-anchor" href="#recovery-is-still-an-experiment" aria-label="Permalink to &quot;Recovery is still an experiment&quot;">​</a></h2><p>Ordinary health healing does not automatically repair local integrity. The Lab uses session-local state and resets, which are not a final medical system. Healing, bleeding control, stabilization and lasting injuries need later design. Do not assume that a bandage already repairs every kind of harm.</p><p><a href="/Syrolands-Public/game-design/combat/body-regions.html">Exact body model and lifecycle</a> · <a href="/Syrolands-Public/game-design/combat/damage.html">Damage and trauma policy</a> · <a href="/Syrolands-Public/game-design/combat/disability.html">Disability limits</a>.</p><p><a href="/Syrolands-Public/guide/combat/overview.html">Back to Combat overview</a></p>',9)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
